ReplacementContent:
"const BOOKMAN_FONT_BASE = `${import.meta.env.BASE_URL}fonts`;
try {
    Font.register({ family: 'BookmanOldStyle', src: `${BOOKMAN_FONT_BASE}/BOOKOS.TTF` });
    Font.register({ family: 'BookmanOldStyle-Bold', src: `${BOOKMAN_FONT_BASE}/BOOKOSB.TTF` });
    Font.register({ family: 'BookmanOldStyle-Italic', src: `${BOOKMAN_FONT_BASE}/BOOKOSI.TTF` });
    Font.register({ family: 'BookmanOldStyle-BoldItalic', src: `${BOOKMAN_FONT_BASE}/BOOKOSBI.TTF` });
} catch {
    // Keep rendering even if system Bookman fonts are unavailable.
}"

